create table RB_AGREEMENT_YHT (AGREEMENT_ID VARCHAR(50) not null  ,MAIN_AGREEMENT_ID VARCHAR(50) null  ,AGREEMENT_STATUS VARCHAR(3) null  ,INTERNAL_KEY INT null  ,PARENT_INTERNAL_KEY INT null  ,BASE_ACCT_NO VARCHAR(50) null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,ACCT_NAME VARCHAR(100) null  ,ALT_ACCT_NAME VARCHAR(100) null  ,ACCT_REAL_FLAG VARCHAR(1) null  ,NEXT_MAX_SEQ_NO VARCHAR(5) null  ,SELF_FLAG VARCHAR(1) null  ,INT_FLAG VARCHAR(1) null  ,SETTLE_IND VARCHAR(1) null  ,YHT_PROD_TYPE VARCHAR(20) null  ,YHT_ACCT_FLAG VARCHAR(1) null  ,YHT_ACCT_LEVEL VARCHAR(1) null  ,YHT_ACCT_MAIN_FLAG VARCHAR(1) null  ,YHT_ACCT_ORG_SCHEMA VARCHAR(2) null  ,ISS_OD_FLAG VARCHAR(1) null  ,SOURCE_TYPE VARCHAR(10) null  ,CLIENT_NO VARCHAR(22) not null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,NON_TRANSPLANT_FLAG VARCHAR(1) null  ,ACCT_SETTLE_METHOD VARCHAR(5) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(AGREEMENT_ID,CLIENT_NO));